package com.mahesh.empleave.notification;import com.mahesh.empleave.user.*;import jakarta.persistence.*;import lombok.*;import java.time.*;@Entity @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) public class Notification{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(optional=false) private AppUser user;@Column(nullable=false) private String message;private LocalDateTime readAt;@Column(nullable=false) private LocalDateTime createdAt=LocalDateTime.now();public Notification(AppUser u,String m){user=u;message=m;}public void markRead(){if(readAt==null)readAt=LocalDateTime.now();}}
